"""Canonical language-machine construction for the policy compiler.

The pipeline is entirely userspace and single threaded:

1. one deterministic residual automaton per distinct atom.  All ``match`` atoms
   share a single prefix trie, because the residual of an exact-match language
   after a word is decided by that word's trie node (a trie is prefix
   injective), so the joint machine costs no product blow-up;
2. the joint product of trie node and non-literal residual vector, enumerated
   breadth-first from the start; the acceptance of a joint state is the rule
   matrix ``allowed(w) == some allow rule matches and no drop rule matches``;
3. Moore style partition refinement, which is monotone in the block count, so
   a compile that can no longer fit the row budget stops immediately;
4. removal of the dead residual, breadth-first renumbering in increasing
   service-label order with ``DENY`` columns ignored, and the row/cell census.

The result is the ``{'accept', 'rows', 'rows_count', 'cells'}`` image of the
contract; ``DENY`` is the target of every transition that leaves the retained
residuals and has no row of its own.
"""
from syntax import ATOM_KINDS, PolicyError

__all__ = ['DENY', 'MAX_ROWS', 'compile_rules', 'TooBig']

DENY = 4294967295
MAX_ROWS = 8192

# A joint machine this large cannot be reduced into the row budget by the
# refinement below, so the compile is abandoned instead of exhausting memory.
MAX_JOINT_STATES = 262144


class TooBig(PolicyError):
    """The compiled machine is beyond the contract's image budget."""


class _Failure(Exception):
    """Internal stop signal: the compile cannot produce a legal image."""


# --------------------------------------------------------------------------- atoms


def _collect(predicate, match_paths, nonliterals, slots, depth, deepest):
    """Register the atoms of one predicate and track its nesting depth."""
    if depth > deepest[0]:
        deepest[0] = depth
    kind = predicate[0]
    if kind in ATOM_KINDS:
        path = predicate[1]
        if kind == 'match':
            if path not in slots:
                slots[path] = len(match_paths)
                match_paths.append(path)
        else:
            key = (kind, path)
            if key not in slots:
                slots[key] = len(nonliterals)
                nonliterals.append(key)
        return
    if kind == 'not':
        _collect(predicate[1], match_paths, nonliterals, slots, depth + 1, deepest)
    else:
        _collect(predicate[1], match_paths, nonliterals, slots, depth + 1, deepest)
        _collect(predicate[2], match_paths, nonliterals, slots, depth + 1, deepest)


def _program(predicate, slots):
    """Postfix program for one predicate; operands are shared atom slots."""
    program = []
    pending = [(predicate, 0)]
    while pending:
        node, stage = pending.pop()
        kind = node[0]
        if kind in ATOM_KINDS:
            program.append(slots[node[1]] if kind == 'match' else slots[(kind, node[1])])
        elif stage == 0:
            pending.append((node, 1))
            pending.append((node[1], 0))
        else:
            program.append(kind)
    return program


def _evaluate(program, flags):
    stack = []
    for item in program:
        if type(item) is int:
            stack.append(flags[item])
        elif item == 'not':
            stack.append(not stack.pop())
        elif item == 'and':
            right = stack.pop()
            stack.append(stack.pop() and right)
        else:
            right = stack.pop()
            stack.append(stack.pop() or right)
    return stack[-1]


# ------------------------------------------------------------------------ machines


def _trie(paths, width):
    """Prefix trie over exact-match paths, plus an explicit dead state."""
    children = [{}]
    for path in paths:
        node = 0
        for symbol in path:
            step = children[node].get(symbol)
            if step is None:
                step = len(children)
                children.append({})
                children[node][symbol] = step
            node = step
    dead = len(children)
    rows = []
    for node in range(dead):
        row = [dead] * width
        for symbol, step in children[node].items():
            row[symbol] = step
        rows.append(row)
    rows.append([dead] * width)
    return rows, dead


def _overlap_rows(width, path, absorbing):
    """Residual automaton of ``endswith``/``contains``.

    State ``i`` means "the longest suffix of the word read so far that is also
    a prefix of the pattern has length i"; state ``len(path)`` is accepting and,
    for ``contains``, absorbing.
    """
    length = len(path)
    rows = []
    for state in range(length + 1):
        row = [0] * width
        for symbol in range(width):
            word = list(path[:state]) + [symbol]
            step = min(length, len(word))
            while step and word[len(word) - step:] != path[:step]:
                step -= 1
            if absorbing and state == length:
                step = length
            row[symbol] = step
        rows.append(row)
    return rows, frozenset([length])


def _prefix_rows(width, path):
    """Residual automaton of ``startswith``: the pattern must be a prefix."""
    length = len(path)
    dead = length + 1
    rows = []
    for state in range(length):
        row = [dead] * width
        row[path[state]] = state + 1
        rows.append(row)
    rows.append([length] * width)
    rows.append([dead] * width)
    return rows, frozenset([length])


def _vectors(machines, finals, width):
    """Enumerate the reachable residual vectors of the non-literal atoms."""
    count = len(machines)
    start = (0,) * count
    ids = {start: 0}
    order = [start]
    position = 0
    while position < len(order):
        vector = order[position]
        position += 1
        for symbol in range(width):
            step = tuple(machines[atom][state][symbol] for atom, state in enumerate(vector))
            if step not in ids:
                ids[step] = len(order)
                order.append(step)
    transitions = []
    masks = []
    for vector in order:
        mask = 0
        for atom, state in enumerate(vector):
            if state in finals[atom]:
                mask |= 1 << atom
        masks.append(mask)
        transitions.append([ids[tuple(machines[atom][state][symbol]
                                      for atom, state in enumerate(vector))]
                            for symbol in range(width)])
    return transitions, masks, ids[start]


# --------------------------------------------------------------------- refinement


def _refine(count, flags, delta, width, limit):
    """Moore partition refinement; returns (block_of_state, blocks)."""
    reject_group = [s for s in range(count) if not flags[s]]
    accept_group = [s for s in range(count) if flags[s]]
    blocks = []
    if reject_group:
        blocks.append(reject_group)
    if accept_group:
        blocks.append(accept_group)
    part = [0] * count
    for index, group in enumerate(blocks):
        for state in group:
            part[state] = index
    get = part.__getitem__
    while True:
        new = [0] * count
        refined = []
        split = False
        for group in blocks:
            if len(group) == 1:
                refined.append(group)
                new[group[0]] = len(refined) - 1
                continue
            buckets = {}
            for state in group:
                key = tuple(map(get, delta[state]))
                bucket = buckets.get(key)
                if bucket is None:
                    buckets[key] = [state]
                else:
                    bucket.append(state)
            if len(buckets) > 1:
                split = True
            for bucket in buckets.values():
                refined.append(bucket)
                index = len(refined) - 1
                for state in bucket:
                    new[state] = index
        part = new
        blocks = refined
        if len(blocks) > limit:
            raise _Failure('image beyond row budget')
        if not split:
            return part, blocks


def _canonical(count, delta, flags, width, columns):
    """Minimal complete machine, dead residual removed, breadth-first labels."""
    part, blocks = _refine(count, flags, delta, width, MAX_ROWS + 1)
    total = len(blocks)
    reduced = []
    accept = []
    for group in blocks:
        representative = group[0]
        reduced.append([part[state] for state in delta[representative]])
        accept.append(bool(flags[representative]))
    start = part[0]

    # Residuals that can still reach an allowed sequence, plus START always.
    live = [False] * total
    queue = [b for b in range(total) if accept[b]]
    for b in queue:
        live[b] = True
    predecessors = [[] for _ in range(total)]
    for b in range(total):
        for target in reduced[b]:
            predecessors[target].append(b)
    head = 0
    while head < len(queue):
        current = queue[head]
        head += 1
        for source in predecessors[current]:
            if not live[source]:
                live[source] = True
                queue.append(source)
    if not live[start]:
        # The empty language: only START survives, with an all-DENY row.
        live = [False] * total
        live[start] = True

    order = [start]
    number = {start: 0}
    head = 0
    while head < len(order):
        current = order[head]
        head += 1
        for target in reduced[current]:
            if live[target] and target not in number:
                number[target] = len(order)
                order.append(target)
    if len(order) > MAX_ROWS:
        raise TooBig('image rows')
    rows = []
    census = 0
    for b in order:
        row = []
        for target in reduced[b]:
            if live[target] and target in number:
                cell = number[target]
                census += 1
            else:
                cell = DENY
            row.append(cell)
        rows.append(row)
    return {'accept': [accept[b] for b in order], 'rows': rows,
            'rows_count': len(order), 'cells': census}


# ------------------------------------------------------------------------- driver


def compile_rules(rules, columns, name_to_column):
    """Compile parsed rules into the canonical image of the contract.

    ``rules`` is the output of :func:`syntax.parse`, ``columns`` the registered
    service labels in increasing order and ``name_to_column`` maps every
    registered name to its column index.  Raises PolicyError on a policy-bound,
    syntax or registry violation and on an oversized image.
    """
    match_paths = []
    nonliterals = []
    slots = {}
    deepest = [0]
    for predicate, _ in rules:
        _collect(predicate, match_paths, nonliterals, slots, 1, deepest)
    if deepest[0] > 16:
        raise PolicyError('predicate depth')
    if len(nonliterals) > 4:
        raise PolicyError('distinct nonliteral atoms')
    width = len(columns)
    if width <= 0:
        raise PolicyError('empty registry')
    try:
        return _compile(rules, match_paths, nonliterals, slots, width, name_to_column)
    except TooBig:
        raise
    except _Failure:
        raise TooBig('image beyond row budget')


def _compile(rules, match_paths, nonliterals, slots, width, name_to_column):
    # Programs and actions for the rules whose predicate is not one match atom.
    programs = []
    actions = []
    simple_allow = frozenset()
    simple_drop = frozenset()
    allow_slots = set()
    drop_slots = set()
    for predicate, allow in rules:
        if predicate[0] == 'match':
            (allow_slots if allow else drop_slots).add(slots[predicate[1]])
        else:
            programs.append(_program(predicate, slots))
            actions.append(allow)
    simple_allow = frozenset(allow_slots)
    simple_drop = frozenset(drop_slots)
    match_index = {path: slots[path] for path in match_paths}

    trie_rows, trie_dead = _trie(match_paths, width)
    terminal = {}
    for path, slot in match_index.items():
        node = 0
        for symbol in path:
            node = trie_rows[node][symbol]
        terminal[node] = slot

    machines = []
    finals = []
    for kind, path in nonliterals:
        symbols = [name_to_column[name] for name in path]
        if kind == 'startswith':
            rows, accepting = _prefix_rows(width, symbols)
        else:
            rows, accepting = _overlap_rows(width, symbols, kind == 'contains')
        machines.append(rows)
        finals.append(accepting)
    vector_next, vector_mask, vector_start = _vectors(machines, finals, width)
    vectors = len(vector_next)

    # Node classes collapse the acceptance matrix for identical node facts.
    classes = []
    class_of = []
    seen = {}
    for node in range(len(trie_rows)):
        slot = terminal.get(node, -1)
        key = (slot, 1 if slot in simple_allow else 0, 1 if slot in simple_drop else 0)
        index = seen.get(key)
        if index is None:
            index = len(classes)
            seen[key] = index
            classes.append(key)
        class_of.append(index)

    atom_count = len(match_paths) + len(nonliterals)
    cache = {}

    def accepts(class_id, vector):
        code = class_id * vectors + vector
        value = cache.get(code)
        if value is None:
            slot, allow_flag, drop_flag = classes[class_id]
            flags = [False] * atom_count
            if slot >= 0:
                flags[slot] = True
            mask = vector_mask[vector]
            for atom in range(len(nonliterals)):
                if mask & (1 << atom):
                    flags[len(match_paths) + atom] = True
            allowed = bool(allow_flag)
            denied = bool(drop_flag)
            for program, action in zip(programs, actions):
                if _evaluate(program, flags):
                    if action:
                        allowed = True
                    else:
                        denied = True
            value = allowed and not denied
            cache[code] = value
        return value

    # Breadth-first enumeration of the joint machine.
    nodes = [0]
    used = [vector_start]
    index = {(0, vector_start): 0}
    delta = []
    head = 0
    append_node = nodes.append
    append_vector = used.append
    while head < len(nodes):
        node = nodes[head]
        vector = used[head]
        head += 1
        row = [0] * width
        for symbol in range(width):
            child = trie_rows[node][symbol]
            step = vector_next[vector][symbol]
            key = (child, step)
            target = index.get(key)
            if target is None:
                if len(nodes) >= MAX_JOINT_STATES:
                    raise _Failure('joint machine')
                target = len(nodes)
                index[key] = target
                append_node(child)
                append_vector(step)
            row[symbol] = target
        delta.append(row)

    count = len(nodes)
    flags = [accepts(class_of[s], used[s]) for s in range(count)]
    return _canonical(count, delta, flags, width, None)
